// Validate and process quest progress update
const { questId, playerId, objectiveId, progress, action, data } = $input.first().json;

// Validate required fields
if (!questId || !playerId) {
  throw new Error('Quest ID and Player ID are required');
}

// Standardize the progress data
const progressData = {
  questId,
  playerId,
  objectiveId: objectiveId || null,
  progress: progress || 0,
  action: action || 'update', // update, complete, abandon, choice
  data: data || {},
  timestamp: new Date().toISOString(),
  sessionId: data.sessionId || `session_${Date.now()}`,
  clientInfo: {
    userAgent: data.userAgent || 'unknown',
    ip: data.ip || 'unknown',
    platform: data.platform || 'unknown'
  }
};

// Add progress metadata
progressData.metadata = {
  isIncremental: action === 'update' && typeof progress === 'number',
  isCompletion: action === 'complete' || progress >= 100,
  isAbandonment: action === 'abandon',
  hasChoice: action === 'choice' && objectiveId,
  timeSpent: data.timeSpent || 0,
  location: data.location || null
};

// Log the progress update
console.log(`Quest progress update: ${action} for quest ${questId}, player ${playerId}`);

return { json: progressData };

// Process quest completion
const questData = $node["Fetch Quest Details"].json;
const playerData = $node["Fetch Player Details"].json;
const progressData = $node["Validate Progress Data"].json;

// Calculate completion statistics
const completionStats = {
  totalTime: progressData.metadata.timeSpent || 0,
  objectivesCompleted: questData.objectives.filter(obj => obj.completed).length,
  totalObjectives: questData.objectives.length,
  completionPercentage: Math.round((questData.objectives.filter(obj => obj.completed).length / questData.objectives.length) * 100),
  difficultyRating: questData.difficulty,
  playerLevel: playerData.stats.level,
  questType: questData.type,
  questCategory: questData.category
};

// Calculate rewards
const rewardCalculation = {
  baseExperience: 100 * questData.difficulty,
  difficultyBonus: Math.round(100 * questData.difficulty * (questData.difficulty / 5)),
  speedBonus: completionStats.totalTime < 1800000 ? Math.round(50 * questData.difficulty) : 0, // Less than 30 minutes
  perfectionBonus: completionStats.completionPercentage === 100 ? Math.round(75 * questData.difficulty) : 0,
  totalExperience: 0,
  goldReward: Math.round(50 * questData.difficulty * (1 + (completionStats.completionPercentage / 100))),
  reputationGain: Math.round(25 * questData.difficulty)
};

rewardCalculation.totalExperience = rewardCalculation.baseExperience + rewardCalculation.difficultyBonus + rewardCalculation.speedBonus + rewardCalculation.perfectionBonus;

// Determine achievement eligibility
const achievements = [];
if (completionStats.completionPercentage === 100) achievements.push('perfect_completion');
if (completionStats.totalTime < 600000) achievements.push('speed_demon'); // Less than 10 minutes
if (questData.difficulty >= 6) achievements.push('legendary_hero');
if (playerData.stats.level <= questData.levelRequirement) achievements.push('underdog');
if (questData.type === 'daily' && new Date().toDateString() === new Date(progressData.timestamp).toDateString()) {
  achievements.push('daily_champion');
}

// Prepare completion data
const completionData = {
  questId: questData.id,
  playerId: playerData._id,
  action: 'complete',
  completionStats,
  rewards: rewardCalculation,
  achievements,
  timestamp: progressData.timestamp,
  sessionId: progressData.sessionId,
  rating: progressData.data.rating || null,
  feedback: progressData.data.feedback || ''
};

console.log(`Quest ${questData.id} completed by player ${playerData._id} with ${completionStats.completionPercentage}%`);

return { json: completionData };

// Process regular progress update
const questData = $node["Fetch Quest Details"].json;
const playerData = $node["Fetch Player Details"].json;
const progressData = $node["Validate Progress Data"].json;

// Find the objective being updated
let targetObjective = null;
if (progressData.objectiveId) {
  targetObjective = questData.objectives.find(obj => obj.id === progressData.objectiveId);
} else {
  // Find first incomplete objective
  targetObjective = questData.objectives.find(obj => !obj.completed);
}

if (!targetObjective) {
  throw new Error('No valid objective found for progress update');
}

// Calculate progress
const previousProgress = targetObjective.current || 0;
const newProgress = Math.min(progressData.progress, targetObjective.required);
const progressDelta = newProgress - previousProgress;
const isCompleted = newProgress >= targetObjective.required;

// Update quest progress
const updatedQuest = { ...questData };
const objectiveIndex = updatedQuest.objectives.findIndex(obj => obj.id === targetObjective.id);
updatedQuest.objectives[objectiveIndex].current = newProgress;
updatedQuest.objectives[objectiveIndex].completed = isCompleted;

// Calculate overall quest progress
const totalObjectives = updatedQuest.objectives.filter(obj => !obj.optional).length;
const completedObjectives = updatedQuest.objectives.filter(obj => !obj.optional && obj.completed).length;
const overallProgress = Math.round((completedObjectives / totalObjectives) * 100);

// Check for milestones
const milestones = [];
if (overallProgress >= 25 && !questData.milestones?.includes('quarter_complete')) {
  milestones.push('quarter_complete');
}
if (overallProgress >= 50 && !questData.milestones?.includes('half_complete')) {
  milestones.push('half_complete');
}
if (overallProgress >= 75 && !questData.milestones?.includes('three_quarters_complete')) {
  milestones.push('three_quarters_complete');
}
if (isCompleted && !targetObjective.completed) {
  milestones.push('objective_completed');
}

// Prepare progress update data
const progressUpdateData = {
  questId: questData.id,
  playerId: playerData._id,
  action: 'update',
  objectiveId: targetObjective.id,
  objectiveTitle: targetObjective.title,
  previousProgress,
  newProgress,
  progressDelta,
  objectiveCompleted: isCompleted,
  overallProgress,
  questCompleted: overallProgress >= 100,
  milestones,
  timestamp: progressData.timestamp,
  sessionId: progressData.sessionId,
  timeSpent: progressData.metadata.timeSpent || 0,
  location: progressData.metadata.location
};

console.log(`Quest progress updated: ${questData.id}, objective ${targetObjective.id}, progress ${newProgress}/${targetObjective.required}`);

return { json: progressUpdateData };

// Process quest abandonment
const questData = $node["Fetch Quest Details"].json;
const playerData = $node["Fetch Player Details"].json;
const progressData = $node["Validate Progress Data"].json;

// Calculate abandonment statistics
const abandonmentStats = {
  timeSpent: progressData.metadata.timeSpent || 0,
  progressAtAbandonment: Math.round((questData.objectives.filter(obj => obj.completed).length / questData.objectives.length) * 100),
  objectivesCompleted: questData.objectives.filter(obj => obj.completed).length,
  totalObjectives: questData.objectives.length,
  difficultyRating: questData.difficulty,
  playerLevel: playerData.stats.level,
  questType: questData.type,
  abandonmentReason: progressData.data.reason || 'manual',
  lastObjective: progressData.objectiveId || null
};

// Analyze abandonment patterns
const abandonmentAnalysis = {
  isEarlyAbandon: abandonmentStats.timeSpent < 300000, // Less than 5 minutes
  isLateAbandon: abandonmentStats.progressAtAbandonment > 75,
  isDifficultyRelated: abandonmentStats.difficultyRating > playerData.stats.level / 10 + 1,
  possibleFrustration: abandonmentStats.progressAtAbandonment < 25 && abandonmentStats.timeSpent > 600000, // Low progress after 10+ minutes
  recommendedDifficultyAdjustment: 0
};

// Recommend difficulty adjustment
if (abandonmentAnalysis.isEarlyAbandon || abandonmentAnalysis.possibleFrustration) {
  abandonmentAnalysis.recommendedDifficultyAdjustment = -1;
} else if (abandonmentAnalysis.isLateAbandon) {
  abandonmentAnalysis.recommendedDifficultyAdjustment = 1;
}

// Prepare abandonment data
const abandonmentData = {
  questId: questData.id,
  playerId: playerData._id,
  action: 'abandon',
  abandonmentStats,
  abandonmentAnalysis,
  timestamp: progressData.timestamp,
  sessionId: progressData.sessionId,
  reason: progressData.data.reason || 'Player choice',
  feedback: progressData.data.feedback || ''
};

console.log(`Quest ${questData.id} abandoned by player ${playerData._id} at ${abandonmentStats.progressAtAbandonment}% progress`);

return { json: abandonmentData };

