// Prepare final response
const progressData = $input.first().json;
const originalData = $node["Validate Progress Data"].json;

// Create appropriate response based on action
let responseData;

switch (progressData.action) {
  case 'complete':
    responseData = {
      success: true,
      action: 'quest_completed',
      questId: progressData.questId,
      playerId: progressData.playerId,
      completionStats: progressData.completionStats,
      rewards: progressData.rewards,
      achievements: progressData.achievements,
      message: `Quest completed with ${progressData.completionStats.completionPercentage}% success rate`,
      timestamp: progressData.timestamp
    };
    break;

  case 'abandon':
    responseData = {
      success: true,
      action: 'quest_abandoned',
      questId: progressData.questId,
      playerId: progressData.playerId,
      abandonmentStats: progressData.abandonmentStats,
      recommendedAdjustment: progressData.abandonmentAnalysis.recommendedDifficultyAdjustment,
      message: `Quest abandoned at ${progressData.abandonmentStats.progressAtAbandonment}% progress`,
      timestamp: progressData.timestamp
    };
    break;

  default:
    responseData = {
      success: true,
      action: 'progress_updated',
      questId: progressData.questId,
      playerId: progressData.playerId,
      objectiveId: progressData.objectiveId,
      objectiveTitle: progressData.objectiveTitle,
      progress: progressData.newProgress,
      progressDelta: progressData.progressDelta,
      objectiveCompleted: progressData.objectiveCompleted,
      overallProgress: progressData.overallProgress,
      milestones: progressData.milestones,
      message: progressData.objectiveCompleted 
        ? `Objective "${progressData.objectiveTitle}" completed!`
        : `Progress updated: ${progressData.newProgress}/${progressData.newProgress + progressData.progressDelta}`,
      timestamp: progressData.timestamp
    };
}

// Add session information
responseData.sessionId = originalData.sessionId;
responseData.processingTime = Date.now() - new Date(originalData.timestamp).getTime();

// Log successful update
console.log(`Progress update successful: ${responseData.action} for quest ${progressData.questId}`);

return { json: responseData };

// Log progress analytics
const progressData = $input.first().json;
const originalData = $node["Validate Progress Data"].json;

const analyticsData = {
  event: `quest_${progressData.action}`,
  timestamp: progressData.timestamp,
  questId: progressData.questId,
  playerId: progressData.playerId,
  sessionId: originalData.sessionId,
  action: progressData.action,
  processingTime: Date.now() - new Date(originalData.timestamp).getTime(),
  clientInfo: originalData.clientInfo
};

// Add action-specific data
switch (progressData.action) {
  case 'complete':
    analyticsData.completionStats = progressData.completionStats;
    analyticsData.rewards = progressData.rewards;
    analyticsData.achievements = progressData.achievements;
    break;
  case 'abandon':
    analyticsData.abandonmentStats = progressData.abandonmentStats;
    analyticsData.abandonmentAnalysis = progressData.abandonmentAnalysis;
    break;
  default:
    analyticsData.progressUpdate = {
      objectiveId: progressData.objectiveId,
      progressDelta: progressData.progressDelta,
      overallProgress: progressData.overallProgress,
      milestones: progressData.milestones
    };
}

console.log('Quest Progress Analytics:', JSON.stringify(analyticsData, null, 2));

return { json: analyticsData };

